grouped.patch:
--- baseline/moe_prefill.hip.cpp
+++ grouped/moe_prefill.hip.cpp
@@ -463,10 +463,16 @@
         if (j < live_tiles) {
           const __half* b = s_act + (j * 16 + sub) * kActStride + s * 32;
           v16h b_lo;
+          __builtin_memcpy(&b_lo, b, 32);
+          acc[j] = Wmma(a_lo, b_lo, acc[j]);
+        }
+      }
+#pragma unroll
+      for (int j = 0; j < kTokTiles; ++j) {
+        if (j < live_tiles) {
+          const __half* b = s_act + (j * 16 + sub) * kActStride + s * 32;
           v16h b_hi;
-          __builtin_memcpy(&b_lo, b, 32);
           __builtin_memcpy(&b_hi, b + 16, 32);
-          acc[j] = Wmma(a_lo, b_lo, acc[j]);
           acc[j] = Wmma(a_hi, b_hi, acc[j]);
         }
       }

swizzle.patch:
--- baseline/moe_prefill.hip.cpp
+++ swizzle/moe_prefill.hip.cpp
@@ -50,7 +50,7 @@
                                                        : 210;
 /// Halves per staged token row: 128 values plus padding (68 dwords) against
 /// bank conflicts on the fragment reads.
-constexpr int kActStride = kStageK + 8;
+constexpr int kActStride = kStageK;

 __device__ __forceinline__ v8f Wmma(v16h a, v16h b, v8f c) {
   return __builtin_amdgcn_wmma_f32_16x16x16_f16_w32(a, b, c);
@@ -413,7 +413,7 @@
       const int chunk = tid + i * kThreads;
       if (chunk < kActChunks) {
         *reinterpret_cast<uint4*>(s_act + (chunk / 16) * kActStride +
-                                  (chunk % 16) * 8) = a_data[i];
+                                  ((chunk % 16) ^ ((chunk / 16) & 7)) * 8) = a_data[i];
       }
     }
   };
@@ -461,12 +461,22 @@
 #pragma unroll
       for (int j = 0; j < kTokTiles; ++j) {
         if (j < live_tiles) {
-          const __half* b = s_act + (j * 16 + sub) * kActStride + s * 32;
+          const __half* b = s_act + (j * 16 + sub) * kActStride;
           v16h b_lo;
+          __builtin_memcpy(&b_lo, b + ((s * 4) ^ (sub & 7)) * 8, 16);
+          __builtin_memcpy(reinterpret_cast<char*>(&b_lo) + 16,
+                           b + ((s * 4 + 1) ^ (sub & 7)) * 8, 16);
+          acc[j] = Wmma(a_lo, b_lo, acc[j]);
+        }
+      }
+#pragma unroll
+      for (int j = 0; j < kTokTiles; ++j) {
+        if (j < live_tiles) {
+          const __half* b = s_act + (j * 16 + sub) * kActStride;
           v16h b_hi;
-          __builtin_memcpy(&b_lo, b, 32);
-          __builtin_memcpy(&b_hi, b + 16, 32);
-          acc[j] = Wmma(a_lo, b_lo, acc[j]);
+          __builtin_memcpy(&b_hi, b + ((s * 4 + 2) ^ (sub & 7)) * 8, 16);
+          __builtin_memcpy(reinterpret_cast<char*>(&b_hi) + 16,
+                           b + ((s * 4 + 3) ^ (sub & 7)) * 8, 16);
           acc[j] = Wmma(a_hi, b_hi, acc[j]);
         }
       }
@@ -1163,7 +1173,7 @@
   // Seven 16-token tiles: each decoded weight fragment feeds seven products
   // instead of six, and the 30 KB of staged activations still let four blocks
   // share a WGP (128 tokens take 35 KB and three).
-  constexpr int kTile = 112;
+  constexpr int kTile = 128;
   // Token tiles per row-block sweep (cold 2048-row Gemma 31B shapes: 2 or 3
   // beat both one and every tile).
   constexpr std::uint32_t kGroup = 2;

